M = [int(x) for x in open('17.txt')]
D = [int(x) for x in M if str(x)[-2:] == '21' and len(str(abs(x)))==5 ]
R = []
for i in range(len(M)-1):
    x, y = M[i], M[i+1]
    if (x in D and y not in D) or (y in D and x not in D):
        if (x**2)+(y**2) >= max(D)**2:
            R.append(x + y)
print(len(R), max(R))

